// Analyze pets for training opportunities
const pets = $input.first().json.data || [];
const trainingCandidates = [];

for (const pet of pets) {
  const trainingAnalysis = analyzeTrainingReadiness(pet);

  if (trainingAnalysis.canTrain) {
    trainingCandidates.push({
      petId: pet.id,
      petName: pet.name,
      level: pet.level,
      energy: pet.energy,
      happiness: pet.happiness,
      bonding: pet.bonding,
      evolutionStage: pet.evolutionStage,
      lastTrained: pet.lastTrained,
      skills: pet.unlockedSkills || [],
      personality: pet.personality,
      traits: pet.traits,
      trainingOpportunities: trainingAnalysis.opportunities,
      recommendedSessions: trainingAnalysis.recommendedSessions,
      priority: calculateTrainingPriority(pet, trainingAnalysis)
    });
  }
}

// Sort by priority and filter for max 5 pets per run
trainingCandidates.sort((a, b) => b.priority - a.priority);
const selectedPets = trainingCandidates.slice(0, 5);

return {
  eligiblePets: selectedPets,
  totalChecked: pets.length,
  candidatesFound: trainingCandidates.length,
  selectedForTraining: selectedPets.length
};

function analyzeTrainingReadiness(pet) {
  const timeSinceLastTraining = pet.lastTrained ? Date.now() - pet.lastTrained : Infinity;
  const hoursSinceTraining = timeSinceLastTraining / (1000 * 60 * 60);

  // Basic readiness checks
  const readiness = {
    energySufficient: pet.energy >= 40,
    moodSuitable: pet.happiness >= 30,
    timeElapsed: hoursSinceTraining >= 4,
    healthOk: pet.currentHealth >= pet.maxHealth * 0.7,
    bondingAdequate: pet.bonding >= 20
  };

  const canTrain = Object.values(readiness).every(check => check);

  // Identify training opportunities
  const opportunities = identifyTrainingOpportunities(pet);

  // Determine recommended sessions
  const recommendedSessions = calculateRecommendedSessions(pet, opportunities, hoursSinceTraining);

  return {
    canTrain,
    readiness,
    opportunities,
    recommendedSessions,
    timeSinceLastTraining: hoursSinceTraining
  };
}

function identifyTrainingOpportunities(pet) {
  const opportunities = [];

  // Basic obedience for young or new pets
  if (pet.evolutionStage <= 1 || !pet.unlockedSkills.includes('sit')) {
    opportunities.push({
      type: 'basic_obedience',
      skills: ['sit', 'stay', 'come'],
      priority: 'high',
      reason: 'Fundamental training needed'
    });
  }

  // Advanced skills for experienced pets
  if (pet.level >= 20 && pet.unlockedSkills.includes('sit')) {
    opportunities.push({
      type: 'advanced_skills',
      skills: ['attack', 'defend', 'agility'],
      priority: 'medium',
      reason: 'Ready for advanced training'
    });
  }

  // Magic skills for magical pets
  if (isMagicalPet(pet) && pet.level >= 15) {
    opportunities.push({
      type: 'magical_training',
      skills: ['magic_control', 'spell_casting'],
      priority: 'medium',
      reason: 'Magical potential detected'
    });
  }

  // Utility skills based on personality
  if (pet.personality.primary === 'curious' || pet.personality.primary === 'adventurous') {
    opportunities.push({
      type: 'utility_skills',
      skills: ['tracking', 'foraging'],
      priority: 'low',
      reason: 'Personality suited for utility skills'
    });
  }

  // Social skills for social pets
  if (pet.personality.primary === 'affectionate' || pet.personality.primary === 'social') {
    opportunities.push({
      type: 'social_skills',
      skills: ['socialize', 'teamwork'],
      priority: 'medium',
      reason: 'Social personality detected'
    });
  }

  return opportunities;
}

function isMagicalPet(pet) {
  return pet.category === 'magical' ||
         pet.category === 'elemental' ||
         pet.category === 'celestial' ||
         pet.traits.some(trait => trait.includes('magic'));
}

function calculateRecommendedSessions(pet, opportunities, hoursSinceTraining) {
  const sessions = [];

  // Prioritize opportunities
  const sortedOpportunities = opportunities.sort((a, b) => {
    const priorityOrder = { high: 0, medium: 1, low: 2 };
    return priorityOrder[a.priority] - priorityOrder[b.priority];
  });

  // Limit sessions based on energy and time
  const maxSessions = Math.min(3, Math.floor(pet.energy / 20));

  for (let i = 0; i < Math.min(maxSessions, sortedOpportunities.length); i++) {
    const opportunity = sortedOpportunities[i];
    const skill = opportunity.skills[0]; // Train first skill in list

    sessions.push({
      skillId: skill,
      method: selectTrainingMethod(pet, opportunity.type),
      intensity: determineIntensity(pet, hoursSinceTraining),
      opportunityType: opportunity.type,
      reason: opportunity.reason
    });
  }

  return sessions;
}

function selectTrainingMethod(pet, trainingType) {
  const methods = {
    basic_obedience: pet.personality.primary === 'playful' ? 'play_training' : 'positive_reinforcement',
    advanced_skills: pet.personality.primary === 'serious' ? 'dominance_training' : 'target_training',
    magical_training: 'shaping',
    utility_skills: pet.personality.primary === 'curious' ? 'lure_training' : 'target_training',
    social_skills: 'model_training'
  };

  return methods[trainingType] || 'positive_reinforcement';
}

function determineIntensity(pet, hoursSinceTraining) {
  if (hoursSinceTraining > 24) return 'moderate';
  if (pet.energy > 70) return 'intense';
  return 'light';
}

function calculateTrainingPriority(pet, analysis) {
  let priority = 0;

  // Higher priority for pets that haven't been trained recently
  if (analysis.timeSinceLastTraining > 24) priority += 5;
  else if (analysis.timeSinceLastTraining > 12) priority += 3;
  else if (analysis.timeSinceLastTraining > 6) priority += 1;

  // Higher priority for young pets
  if (pet.evolutionStage <= 1) priority += 3;
  else if (pet.evolutionStage <= 2) priority += 1;

  // Higher priority for pets with good energy and mood
  if (pet.energy > 70) priority += 2;
  if (pet.happiness > 70) priority += 1;

  // Higher priority for pets with high bonding
  if (pet.bonding > 80) priority += 2;

  // Priority based on training opportunities
  for (const opportunity of analysis.opportunities) {
    if (opportunity.priority === 'high') priority += 4;
    else if (opportunity.priority === 'medium') priority += 2;
    else priority += 1;
  }

  return Math.min(20, priority); // Cap at 20
}

