// Execute training sessions for selected pets
const eligiblePets = $input.first().json.eligiblePets || [];
const trainingResults = [];

for (const petCandidate of eligiblePets) {
  try {
    console.log(`Starting training for pet: ${petCandidate.petName}`);

    // Get detailed pet information
    const petResponse = await $helpers.httpRequest({
      method: 'GET',
      url: `http://localhost:3000/api/pets/${petCandidate.petId}`,
      headers: { 'Content-Type': 'application/json' }
    });

    const pet = petResponse.data;
    const petResults = [];

    // Execute each recommended training session
    for (const session of petCandidate.recommendedSessions) {
      try {
        const trainingResult = await executeTrainingSession(pet, session);
        petResults.push(trainingResult);

        // Update pet data with training results
        if (trainingResult.success) {
          pet.energy = Math.max(0, pet.energy - trainingResult.energyConsumed);
          pet.lastTrained = Date.now();

          // Add new skills if learned
          if (trainingResult.skillLearned) {
            pet.unlockedSkills = pet.unlockedSkills || [];
            if (!pet.unlockedSkills.includes(session.skillId)) {
              pet.unlockedSkills.push(session.skillId);
            }
          }
        }

        // Add delay between sessions
        await new Promise(resolve => setTimeout(resolve, 1000));

      } catch (error) {
        console.error(`Training session failed for ${pet.name}:`, error);
        petResults.push({
          success: false,
          skill: session.skillId,
          error: error.message,
          method: session.method
        });
      }
    }

    // Calculate overall training result for this pet
    const successCount = petResults.filter(r => r.success).length;
    const overallSuccess = successCount > 0;

    trainingResults.push({
      petId: petCandidate.petId,
      petName: petCandidate.petName,
      sessionsCompleted: petResults.length,
      successfulSessions: successCount,
      overallSuccess,
      sessionResults: petResults,
      totalEnergyConsumed: petResults.reduce((sum, r) => sum + (r.energyConsumed || 0), 0),
      totalExperienceGained: petResults.reduce((sum, r) => sum + (r.experienceGained || 0), 0),
      newSkillsLearned: petResults.filter(r => r.skillLearned).map(r => r.skill),
      timestamp: new Date().toISOString()
    });

    // Add delay between pets
    await new Promise(resolve => setTimeout(resolve, 2000));

  } catch (error) {
    console.error(`Training failed for pet ${petCandidate.petName}:`, error);
    trainingResults.push({
      petId: petCandidate.petId,
      petName: petCandidate.petName,
      success: false,
      error: error.message,
      timestamp: new Date().toISOString()
    });
  }
}

return {
  processedPets: eligiblePets.length,
  totalSessions: trainingResults.reduce((sum, r) => sum + (r.sessionsCompleted || 0), 0),
  successfulSessions: trainingResults.reduce((sum, r) => sum + (r.successfulSessions || 0), 0),
  results: trainingResults
};

async function executeTrainingSession(pet, session) {
  const endpoint = `http://localhost:3000/api/pets/${pet.id}/train`;
  const payload = {
    skillId: session.skillId,
    method: session.method,
    intensity: session.intensity,
    options: {
      location: 'training_ground',
      equipment: ['treats', 'clicker'],
      performer: 'auto_training_system'
    }
  };

  const response = await $helpers.httpRequest({
    method: 'POST',
    url: endpoint,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload)
  });

  return {
    success: true,
    skill: session.skillId,
    method: session.method,
    intensity: session.intensity,
    ...response.data.results,
    sessionType: session.opportunityType
  };
}

// Create comprehensive training summary
const data = $input.first().json;
const results = data.results || [];

const summary = {
  processingDate: new Date().toISOString(),
  statistics: {
    petsProcessed: data.processedPets || 0,
    totalSessions: data.totalSessions || 0,
    successfulSessions: data.successfulSessions || 0,
    successRate: data.totalSessions > 0 ? ((data.successfulSessions / data.totalSessions) * 100).toFixed(1) : 0
  },
  skillProgress: analyzeSkillProgress(results),
  petResults: results.map(result => ({
    petId: result.petId,
    petName: result.petName,
    sessionsCompleted: result.sessionsCompleted,
    successfulSessions: result.successfulSessions,
    successRate: result.sessionsCompleted > 0 ? ((result.successfulSessions / result.sessionsCompleted) * 100).toFixed(1) : 0,
    energyConsumed: result.totalEnergyConsumed,
    experienceGained: result.totalExperienceGained,
    newSkills: result.newSkillsLearned || [],
    overallSuccess: result.overallSuccess,
    timestamp: result.timestamp
  })),
  recommendations: generateTrainingRecommendations(results),
  notifications: generateTrainingNotifications(results)
};

return summary;

function analyzeSkillProgress(results) {
  const skillStats = {};

  for (const petResult of results) {
    if (petResult.sessionResults) {
      for (const session of petResult.sessionResults) {
        if (session.success && session.skill) {
          if (!skillStats[session.skill]) {
            skillStats[session.skill] = {
              attempts: 0,
              successes: 0,
              petsLearned: 0
            };
          }

          skillStats[session.skill].attempts++;
          if (session.success) {
            skillStats[session.skill].successes++;
          }
          if (session.skillLearned) {
            skillStats[session.skill].petsLearned++;
          }
        }
      }
    }
  }

  // Calculate success rates
  for (const skill of Object.keys(skillStats)) {
    const stats = skillStats[skill];
    stats.successRate = stats.attempts > 0 ? ((stats.successes / stats.attempts) * 100).toFixed(1) : 0;
  }

  return skillStats;
}

function generateTrainingRecommendations(results) {
  const recommendations = [];

  // Analyze failed sessions
  const failedSessions = [];
  const successfulSessions = [];

  for (const petResult of results) {
    if (petResult.sessionResults) {
      for (const session of petResult.sessionResults) {
        if (session.success) {
          successfulSessions.push(session);
        } else {
          failedSessions.push(session);
        }
      }
    }
  }

  // Method effectiveness analysis
  const methodStats = {};
  for (const session of [...failedSessions, ...successfulSessions]) {
    if (!methodStats[session.method]) {
      methodStats[session.method] = { attempts: 0, successes: 0 };
    }
    methodStats[session.method].attempts++;
    if (session.success) {
      methodStats[session.method].successes++;
    }
  }

  // Find least effective method
  let leastEffectiveMethod = null;
  let lowestSuccessRate = 100;

  for (const [method, stats] of Object.entries(methodStats)) {
    const successRate = stats.attempts > 0 ? (stats.successes / stats.attempts) * 100 : 0;
    if (successRate < lowestSuccessRate && stats.attempts >= 3) {
      lowestSuccessRate = successRate;
      leastEffectiveMethod = method;
    }
  }

  if (leastEffectiveMethod && lowestSuccessRate < 60) {
    recommendations.push({
      type: 'method_optimization',
      title: 'Training Method Optimization',
      message: `Consider alternative methods to ${leastEffectiveMethod} (success rate: ${lowestSuccessRate.toFixed(1)}%)`,
      priority: 'medium'
    });
  }

  // Energy management recommendations
  const highEnergyPets = results.filter(r => r.totalEnergyConsumed > 60);
  if (highEnergyPets.length > 0) {
    recommendations.push({
      type: 'energy_management',
      title: 'Energy Management',
      message: `${highEnergyPets.length} pet(s) consumed high energy during training. Consider scheduling more rest.`,
      priority: 'low'
    });
  }

  // Skill variety recommendations
  const skillTypes = [...new Set(successfulSessions.map(s => s.sessionType))];
  if (skillTypes.length < 3 && successfulSessions.length > 5) {
    recommendations.push({
      type: 'skill_variety',
      title: 'Training Variety',
      message: 'Consider diversifying training types to provide balanced skill development.',
      priority: 'low'
    });
  }

  return recommendations;
}

function generateTrainingNotifications(results) {
  const notifications = [];

  // Successful training sessions
  const successfulPets = results.filter(r => r.overallSuccess);
  if (successfulPets.length > 0) {
    notifications.push({
      type: 'training_success',
      title: '📚 Training Sessions Completed',
      message: `${successfulPets.length} pet(s) completed training successfully!`,
      pets: successfulPets.map(r => ({
        name: r.petName,
        sessions: r.successfulSessions,
        newSkills: r.newSkills.length
      })),
      priority: 'normal'
    });
  }

  // New skills learned
  const petsWithNewSkills = results.filter(r => r.newSkills && r.newSkills.length > 0);
  if (petsWithNewSkills.length > 0) {
    notifications.push({
      type: 'new_skills',
      title: '🎯 New Skills Learned!',
      message: `${petsWithNewSkills.length} pet(s) learned new skills!`,
      pets: petsWithNewSkills.map(r => ({
        name: r.petName,
        skills: r.newSkills
      })),
      priority: 'high'
    });
  }

  // Failed training sessions
  const failedPets = results.filter(r => !r.overallSuccess);
  if (failedPets.length > 0) {
    notifications.push({
      type: 'training_issues',
      title: '⚠️ Training Difficulties',
      message: `${failedPets.length} pet(s) experienced training difficulties`,
      pets: failedPets.map(r => ({ name: r.petName })),
      priority: 'medium'
    });
  }

  return notifications;
}

// Handle case where no pets need training
const data = $input.first().json;

return {
  message: 'Training check completed',
  timestamp: new Date().toISOString(),
  petsChecked: data.totalChecked || 0,
  eligibleFound: data.candidatesFound || 0,
  status: 'no_training_needed',
  nextCheck: new Date(Date.now() + 6 * 60 * 60 * 1000).toISOString() // 6 hours from now
};
